import 'package:flutter/material.dart';

// ═══════════════ نموذج الحديث ═══════════════
class Hadith {
  final String id;
  final int partNumber;
  final String categoryId;
  final String titleAr, titleEn;
  final String narratorAr, narratorEn;
  final String textAr, textEn;
  final String source;
  final String grade;
  final List<String> tags;
  const Hadith({
    required this.id, required this.partNumber, required this.categoryId,
    required this.titleAr, required this.titleEn,
    required this.narratorAr, required this.narratorEn,
    required this.textAr, required this.textEn,
    required this.source, required this.grade,
    this.tags = const [],
  });
}

// ═══════════════ نموذج الجزء ═══════════════
class HadithPart {
  final int number;
  final String titleAr, titleEn;
  final IconData icon;
  final bool available;
  const HadithPart({
    required this.number, required this.titleAr, required this.titleEn,
    required this.icon, this.available = false,
  });
}

// ═══════════════ نموذج التصنيف ═══════════════
class HadithCategory {
  final String id, nameAr, nameEn;
  final IconData icon;
  const HadithCategory({
    required this.id, required this.nameAr, required this.nameEn,
    required this.icon,
  });
}

