    textAr: 'قَالُوا: يَا رَسُولَ اللَّهِ، أَمَّا السَّلَامُ عَلَيْكَ فَقَدْ عَرَفْنَاهُ، فَكَيْفَ الصَّلَاةُ عَلَيْكَ؟ قَالَ: قُولُوا: «اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ».',
    textEn: 'They said: O Messenger of Allah, as for greeting you we know it. How should we send blessings upon you? He said: "Say: O Allah, send blessings upon Muhammad and the family of Muhammad, as You sent blessings upon Ibrahim and the family of Ibrahim. You are Praiseworthy, Glorious. O Allah, bless Muhammad and the family of Muhammad, as You blessed Ibrahim and the family of Ibrahim. You are Praiseworthy, Glorious."',
    source: 'صحيح البخاري 6357 • صحيح مسلم 406',
    grade: 'صحيح • متفق عليه',
    tags: ['الصلاة على النبي', 'التشهد'],
  ),
  Hadith(
    id: 'P04-H014', partNumber: 4, categoryId: 'p_tashahhud',
    titleAr: 'الاستعاذة من أربع في التشهد', titleEn: 'Seeking Refuge from Four',
    narratorAr: 'أبو هريرة رضي الله عنه', narratorEn: 'Abu Hurayrah',
    textAr: 'إِذَا تَشَهَّدَ أَحَدُكُمْ فَلْيَسْتَعِذْ بِاللَّهِ مِنْ أَرْبَعٍ، يَقُولُ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ، وَمِنْ عَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ.',
    textEn: 'When one of you finishes the tashahhud, let him seek refuge in Allah from four: "O Allah, I seek refuge in You from the punishment of Hell, the punishment of the grave, the trials of life and death, and the evil of the trial of the Antichrist."',
    source: 'صحيح مسلم 588',
    grade: 'صحيح',
    tags: ['التشهد', 'الدعاء', 'الدجال'],
  ),
  Hadith(
