    textEn: 'When we prayed with the Prophet ﷺ we used to say: "Peace be upon you and Allah\'s mercy" pointing with our hands to both sides. The Prophet ﷺ said: "Why do you gesture with your hands like the tails of wild horses? It is enough for one of you to place his hand on his thigh and greet his brother on his right and left."',
