    textAr: 'مَنِ اغْتَسَلَ يَوْمَ الْجُمُعَةِ غُسْلَ الْجَنَابَةِ ثُمَّ رَاحَ فَكَأَنَّمَا قَرَّبَ بَدَنَةً، وَمَنْ رَاحَ فِي السَّاعَةِ الثَّانِيَةِ فَكَأَنَّمَا قَرَّبَ بَقَرَةً، وَمَنْ رَاحَ فِي السَّاعَةِ الثَّالِثَةِ فَكَأَنَّمَا قَرَّبَ كَبْشًا أَقْرَنَ، وَمَنْ رَاحَ فِي السَّاعَةِ الرَّابِعَةِ فَكَأَنَّمَا قَرَّبَ دَجَاجَةً، وَمَنْ رَاحَ فِي السَّاعَةِ الْخَامِسَةِ فَكَأَنَّمَا قَرَّبَ بَيْضَةً.',
    textEn: 'Whoever performs ghusl on Friday like the ghusl of janabah, then goes early, it is as if he sacrificed a camel. The second hour — a cow. The third — a horned ram. The fourth — a chicken. The fifth — an egg.',
    source: 'صحيح البخاري 881 • صحيح مسلم 850', grade: 'صحيح • متفق عليه',
    tags: ['الجمعة', 'التبكير']),
  Hadith(id: 'P05-H006', partNumber: 5, categoryId: 'j_eid',
    titleAr: 'صلاة العيد قبل الخطبة', titleEn: 'Eid Prayer Before Khutbah',
    narratorAr: 'ابن عباس رضي الله عنهما', narratorEn: 'Ibn Abbas',
    textAr: 'شَهِدْتُ الْعِيدَ مَعَ رَسُولِ اللَّهِ ﷺ وَأَبِي بَكْرٍ وَعُمَرَ وَعُثْمَانَ رَضِيَ اللَّهُ عَنْهُمْ، فَكُلُّهُمْ كَانُوا يُصَلُّونَ قَبْلَ الْخُطْبَةِ.',
    textEn: 'I attended Eid with the Prophet ﷺ, Abu Bakr, Umar and Uthman — all of them prayed before the khutbah.',
    source: 'صحيح البخاري 962', grade: 'صحيح',
    tags: ['العيد', 'صلاة العيد']),
  Hadith(id: 'P05-H007', partNumber: 5, categoryId: 'j_eid',
    titleAr: 'مخالفة الطريق يوم العيد', titleEn: 'Taking Different Routes on Eid',
    narratorAr: 'جابر بن عبد الله رضي الله عنهما', narratorEn: 'Jabir ibn Abdullah',
    textAr: 'كَانَ النَّبِيُّ ﷺ إِذَا كَانَ يَوْمُ عِيدٍ خَالَفَ الطَّرِيقَ.',
    textEn: 'When it was the day of Eid, the Prophet ﷺ would take a different route (back).',
    source: 'صحيح البخاري 986', grade: 'صحيح',
    tags: ['العيد', 'سنن العيد']),
  Hadith(id: 'P05-H008', partNumber: 5, categoryId: 'j_funeral',
    titleAr: 'فضل صلاة الجنازة', titleEn: 'Virtue of Funeral Prayer',
    narratorAr: 'أبو هريرة رضي الله عنه', narratorEn: 'Abu Hurayrah',
    textAr: 'مَنْ شَهِدَ الْجَنَازَةَ حَتَّى يُصَلَّى عَلَيْهَا فَلَهُ قِيرَاطٌ، وَمَنْ شَهِدَهَا حَتَّى تُدْفَنَ فَلَهُ قِيرَاطَانِ. قِيلَ: وَمَا الْقِيرَاطَانِ؟ قَالَ: مِثْلُ الْجَبَلَيْنِ الْعَظِيمَيْنِ.',
    textEn: 'Whoever attends a funeral until prayer is offered has a qirat. Whoever attends until burial has two qirats. It was asked: "What are two qirats?" He said: "Like two great mountains."',
    source: 'صحيح البخاري 1325 • صحيح مسلم 945', grade: 'صحيح • متفق عليه',
    tags: ['الجنائز', 'صلاة الجنازة']),
  Hadith(id: 'P05-H009', partNumber: 5, categoryId: 'j_funeral',
    titleAr: 'الدعاء للميت', titleEn: 'Dua for the Deceased',
    narratorAr: 'عوف بن مالك رضي الله عنه', narratorEn: 'Awf ibn Malik',
    textAr: 'سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ فِي صَلَاةِ الْجَنَازَةِ: اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ وَعَافِهِ وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ.',
    textEn: 'I heard the Messenger of Allah ﷺ say in the funeral prayer: "O Allah, forgive him and have mercy on him, grant him safety and pardon him, honor his resting place, and wash him with water, snow, and hail, and cleanse him from sins as a white garment is cleansed from filth."',
    source: 'صحيح مسلم 963', grade: 'صحيح',
    tags: ['الجنائز', 'الدعاء للميت']),
  Hadith(id: 'P05-H010', partNumber: 5, categoryId: 'j_funeral',
    titleAr: 'النهي عن النياحة', titleEn: 'Prohibition of Wailing',
    narratorAr: 'عبد الله بن مسعود رضي الله عنه', narratorEn: 'Abdullah ibn Masud',
    textAr: 'لَيْسَ مِنَّا مَنْ لَطَمَ الْخُدُودَ وَشَقَّ الْجُيُوبَ وَدَعَا بِدَعْوَى الْجَاهِلِيَّةِ.',
    textEn: 'He is not one of us who slaps his cheeks, tears his clothes, and cries out with the cry of the days of ignorance.',
    source: 'صحيح البخاري 1294 • صحيح مسلم 103', grade: 'صحيح • متفق عليه',
    tags: ['الجنائز', 'الصبر']),
];

