    titleAr: 'اليد العليا خير من السفلى', titleEn: 'Upper Hand is Better',
    narratorAr: 'حكيم بن حزام رضي الله عنه', narratorEn: 'Hakim ibn Hizam',
    textAr: 'الْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى، وَابْدَأْ بِمَنْ تَعُولُ، وَخَيْرُ الصَّدَقَةِ عَنْ ظَهْرِ غِنًى، وَمَنْ يَسْتَعْفِفْ يُعِفَّهُ اللَّهُ، وَمَنْ يَسْتَغْنِ يُغْنِهِ اللَّهُ.',
