    textAr: 'وَقَفَ رَسُولُ اللَّهِ ﷺ فِي حَجَّةِ الْوَدَاعِ، فَجَعَلُوا يَسْأَلُونَهُ، فَجَاءَهُ رَجُلٌ فَقَالَ: لَمْ أَشْعُرْ فَحَلَقْتُ قَبْلَ أَنْ أَنْحَرَ، فَقَالَ: اذْبَحْ وَلَا حَرَجَ. وَجَاءَ آخَرُ فَقَالَ: لَمْ أَشْعُرْ فَنَحَرْتُ قَبْلَ أَنْ أَرْمِيَ، قَالَ: ارْمِ وَلَا حَرَجَ.',
    textEn: 'The Messenger of Allah ﷺ stood at Arafah during the Farewell Hajj, and people began asking him. A man said: "I did not realize and I shaved before sacrificing." He said: "Sacrifice, no blame." Another said: "I did not realize and I sacrificed before stoning." He said: "Stone, no blame."',
