    textAr: 'قَالَ اللَّهُ تَعَالَى: أَنَا عِنْدَ ظَنِّ عَبْدِي بِي، وَأَنَا مَعَهُ إِذَا ذَكَرَنِي، فَإِنْ ذَكَرَنِي فِي نَفْسِهِ ذَكَرْتُهُ فِي نَفْسِي، وَإِنْ ذَكَرَنِي فِي مَلَإٍ ذَكَرْتُهُ فِي مَلَإٍ خَيْرٍ مِنْهُمْ.',
    textEn: 'Allah says: "I am as My servant thinks of Me, and I am with him when he remembers Me. If he remembers Me to himself, I remember him to Myself. If he remembers Me in a gathering, I remember him in a better gathering."',
