  Hadith(id: 'P09-H008', partNumber: 9, categoryId: 'd_dua',
    titleAr: 'الدعاء بين السجدتين', titleEn: 'Dua Between Two Sujoods',
    narratorAr: 'حذيفة بن اليمان رضي الله عنه', narratorEn: 'Hudhayfah ibn al-Yaman',
    textAr: 'كَانَ يَقُولُ بَيْنَ السَّجْدَتَيْنِ: رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي.',
