    titleAr: 'سيد الاستغفار', titleEn: 'The Master of Istighfar',
    narratorAr: 'شداد بن أوس رضي الله عنه', narratorEn: 'Shaddad ibn Aws',
    textAr: 'سَيِّدُ الِاسْتِغْفَارِ أَنْ تَقُولَ: اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ.',
    textEn: 'The master of istighfar is: "O Allah, You are my Lord, there is no god but You. You created me and I am Your servant. I keep Your covenant and promise as much as I can. I seek refuge in You from the evil I have done. I acknowledge Your favor upon me, and I acknowledge my sin — so forgive me, for none forgives sins but You."',
    source: 'صحيح البخاري 6306', grade: 'صحيح',
    tags: ['الاستغفار', 'الدعاء']),
  Hadith(id: 'P09-H010', partNumber: 9, categoryId: 'd_dhikr',
    titleAr: 'الصلاة على النبي ﷺ', titleEn: 'Salat on the Prophet ﷺ',
    narratorAr: 'أُبي بن كعب رضي الله عنه', narratorEn: 'Ubay ibn Ka\'b',
    textAr: 'إِذَا تَكْفِي هَمَّكَ وَيُغْفَرُ لَكَ ذَنْبُكَ.',
    textEn: 'It will suffice for your worries and your sins will be forgiven.',
    source: 'جامع الترمذي 2457', grade: 'حسن',
    tags: ['الصلاة على النبي', 'الذكر']),
];

