    textAr: 'لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ إِلَّا بِإِحْدَى ثَلَاثٍ: النَّفْسُ بِالنَّفْسِ، وَالثَّيِّبُ الزَّانِي، وَالْمَارِقُ مِنَ الدِّينِ التَّارِكُ لِلْجَمَاعَةِ.',
    textEn: 'The blood of a Muslim who testifies that there is no god but Allah and that I am His Messenger is not lawful except in three cases: a life for a life, the married adulterer, and the one who abandons the religion and separates from the community.',
    source: 'صحيح البخاري 6878 • صحيح مسلم 1676', grade: 'صحيح • متفق عليه',
    tags: ['الدماء', 'الكبائر']),
  Hadith(id: 'P14-H007', partNumber: 14, categoryId: 's_words',
    titleAr: 'الكذب', titleEn: 'Lying',
    narratorAr: 'عبد الله بن مسعود رضي الله عنه', narratorEn: 'Abdullah ibn Masud',
    textAr: 'وَإِيَّاكُمْ وَالْكَذِبَ، فَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ، وَإِنَّ الْفُجُورَ يَهْدِي إِلَى النَّارِ.',
    textEn: 'Beware of lying, for lying leads to immorality, and immorality leads to the Fire.',
    source: 'صحيح البخاري 6094 • صحيح مسلم 2607', grade: 'صحيح • متفق عليه',
    tags: ['الكذب']),
  Hadith(id: 'P14-H008', partNumber: 14, categoryId: 's_words',
    titleAr: 'الغيبة', titleEn: 'Backbiting',
    narratorAr: 'أبو هريرة رضي الله عنه', narratorEn: 'Abu Hurayrah',
    textAr: 'أَتَدْرُونَ مَا الْغِيبَةُ؟ قَالُوا: اللَّهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: ذِكْرُكَ أَخَاكَ بِمَا يَكْرَهُ.',
    textEn: 'Do you know what backbiting is? They said: Allah and His Messenger know best. He said: Mentioning your brother in a way he dislikes.',
    source: 'صحيح مسلم 2589', grade: 'صحيح',
    tags: ['الغيبة', 'اللسان']),
  Hadith(id: 'P14-H009', partNumber: 14, categoryId: 's_words',
    titleAr: 'النميمة', titleEn: 'Gossip',
    narratorAr: 'ابن عباس رضي الله عنهما', narratorEn: 'Ibn Abbas',
    textAr: 'أَمَّا أَحَدُهُمَا فَكَانَ يَمْشِي بِالنَّمِيمَةِ، وَأَمَّا الْآخَرُ فَكَانَ لَا يَسْتَتِرُ مِنْ بَوْلِهِ.',
    textEn: '(The punishment of one was because) he used to walk with gossip, and the other did not protect himself from his urine.',
    source: 'صحيح البخاري 218 • صحيح مسلم 292', grade: 'صحيح • متفق عليه',
    tags: ['النميمة']),
  Hadith(id: 'P14-H010', partNumber: 14, categoryId: 's_words',
    titleAr: 'الكبر', titleEn: 'Arrogance',
    narratorAr: 'عبد الله بن مسعود رضي الله عنه', narratorEn: 'Abdullah ibn Masud',
    textAr: 'لَا يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ كِبْرٍ.',
    textEn: 'No one who has an atom\'s weight of arrogance in his heart will enter Paradise.',
    source: 'صحيح مسلم 91', grade: 'صحيح',
    tags: ['الكبر']),
];

