    textAr: 'رَأَيْتُ رَسُولَ اللَّهِ ﷺ رَمَى الْجَمْرَةَ يَوْمَ النَّحْرِ ضُحًى، وَأَمَّا بَعْدُ فَإِذَا زَالَتِ الشَّمْسُ.',
    textEn: 'I saw the Messenger of Allah ﷺ stoning the Jamrah on the day of sacrifice in the forenoon; as for after that, it was when the sun declined.',
    source: 'صحيح مسلم 1299', grade: 'صحيح',
    tags: ['حجة الوداع']),
];

