    textAr: 'الْأَنْبِيَاءُ إِخْوَةٌ لِعَلَّاتٍ، أُمَّهَاتُهُمْ شَتَّى وَدِينُهُمْ وَاحِدٌ.',
    textEn: 'The Prophets are brothers of different mothers, their mothers are different but their religion is one.',
