    textAr: 'أَنَا أَوْلَى النَّاسِ بِابْنِ مَرْيَمَ فِي الدُّنْيَا وَالْآخِرَةِ، وَالْأَنْبِيَاءُ إِخْوَةٌ لِعَلَّاتٍ، لَيْسَ بَيْنِي وَبَيْنَ عِيسَى نَبِيٌّ.',
