    textAr: 'جَاءَ مَلَكُ الْمَوْتِ إِلَى مُوسَى عَلَيْهِ السَّلَامُ فَقَالَ لَهُ: أَجِبْ رَبَّكَ.',
    textEn: 'The angel of death came to Musa (as) and said: "Respond to your Lord."',
