    narratorAr: 'أبو هريرة رضي الله عنه', narratorEn: 'Abu Hurayrah',
    textAr: 'بَيْنَمَا أَيُّوبُ يَغْتَسِلُ عُرْيَانًا خَرَّ عَلَيْهِ رِجْلُ جَرَادٍ مِنْ ذَهَبٍ، فَجَعَلَ أَيُّوبُ يَحْثِي فِي ثَوْبِهِ، فَنَادَاهُ رَبُّهُ: يَا أَيُّوبُ أَلَمْ أَكُنْ أَغْنَيْتُكَ عَمَّا تَرَى؟ قَالَ: بَلَى يَا رَبِّ، وَلَكِنْ لَا غِنَى لِي عَنْ بَرَكَتِكَ.',
    textEn: 'While Ayyub was bathing naked, a swarm of golden locusts fell upon him. He began gathering them into his garment. His Lord called: "O Ayyub, did I not enrich you from what you see?" He said: "Yes, my Lord, but I have no need beyond Your blessing."',
