    narratorAr: 'أبو هريرة رضي الله عنه', narratorEn: 'Abu Hurayrah',
    textAr: 'كَانَ ثَلَاثَةٌ فِي بَنِي إِسْرَائِيلَ: أَبْرَصُ وَأَقْرَعُ وَأَعْمَى، فَأَرَادَ اللَّهُ أَنْ يَبْتَلِيَهُمْ.',
    textEn: 'There were three men among the Children of Israel: a leper, a bald man, and a blind man. Allah wanted to test them.',
