    textAr: 'إِنَّ فِتْيَةً آمَنُوا بِرَبِّهِمْ فَزَادَهُمْ هُدًى.',
    textEn: 'Indeed, young men believed in their Lord and He increased them in guidance.',
    source: 'صحيح البخاري 3619', grade: 'صحيح',
    tags: ['أصحاب الكهف']),
  Hadith(id: 'P18-H008', partNumber: 18, categoryId: 'pr_stories',
    titleAr: 'قصة قاتل المائة', titleEn: 'The Killer of 100',
    narratorAr: 'أبو سعيد الخدري رضي الله عنه', narratorEn: 'Abu Sa\'id al-Khudri',
    textAr: 'كَانَ فِي بَنِي إِسْرَائِيلَ رَجُلٌ قَتَلَ تِسْعَةً وَتِسْعِينَ إِنْسَانًا، ثُمَّ سَأَلَ عَنْ أَعْلَمِ أَهْلِ الْأَرْضِ.',
    textEn: 'There was a man among Bani Israel who killed ninety-nine people, then asked about the most knowledgeable person on earth.',
    source: 'صحيح البخاري 3470 • صحيح مسلم 2766', grade: 'صحيح • متفق عليه',
    tags: ['التوبة', 'الرحمة']),
  Hadith(id: 'P18-H009', partNumber: 18, categoryId: 'pr_stories',
    titleAr: 'أصحاب الأخدود', titleEn: 'People of the Ditch',
    narratorAr: 'صهيب رضي الله عنه', narratorEn: 'Suhayb',
    textAr: 'كَانَ مَلِكٌ فِيمَنْ كَانَ قَبْلَكُمْ، وَكَانَ لَهُ سَاحِرٌ، فَلَمَّا كَبِرَ السَّاحِرُ قَالَ لِلْمَلِكِ: إِنِّي قَدْ كَبِرْتُ فَابْعَثْ إِلَيَّ غُلَامًا أُعَلِّمْهُ السِّحْرَ.',
    textEn: 'There was a king among those before you, and he had a magician. When the magician grew old he said to the king: "I have grown old, send me a boy to teach magic."',
