    textAr: 'أَنْتَ مِنِّي بِمَنْزِلَةِ هَارُونَ مِنْ مُوسَى، إِلَّا أَنَّهُ لَا نَبِيَّ بَعْدِي.',
    textEn: 'You are to me as Harun was to Musa, except that there is no prophet after me.',
    source: 'صحيح البخاري 4416 • صحيح مسلم 2404', grade: 'صحيح • متفق عليه',
    tags: ['علي']),
  Hadith(id: 'P19-H005', partNumber: 19, categoryId: 'cp_sahaba',
    titleAr: 'العشرة المبشرون بالجنة', titleEn: 'Ten Given Glad Tidings',
    narratorAr: 'عبد الرحمن بن عوف رضي الله عنه', narratorEn: 'Abdur-Rahman ibn Awf',
    textAr: 'أَبُو بَكْرٍ فِي الْجَنَّةِ، وَعُمَرُ فِي الْجَنَّةِ، وَعُثْمَانُ فِي الْجَنَّةِ، وَعَلِيٌّ فِي الْجَنَّةِ، وَطَلْحَةُ فِي الْجَنَّةِ، وَالزُّبَيْرُ فِي الْجَنَّةِ، وَعَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ فِي الْجَنَّةِ، وَسَعْدُ بْنُ أَبِي وَقَّاصٍ فِي الْجَنَّةِ، وَسَعِيدُ بْنُ زَيْدٍ فِي الْجَنَّةِ، وَأَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ فِي الْجَنَّةِ.',
    textEn: 'Abu Bakr in Paradise, Umar in Paradise, Uthman in Paradise, Ali in Paradise, Talhah in Paradise, az-Zubayr in Paradise, Abdur-Rahman ibn Awf in Paradise, Sa\'d ibn Abi Waqqas in Paradise, Sa\'id ibn Zayd in Paradise, and Abu Ubaydah ibn al-Jarrah in Paradise.',
    source: 'جامع الترمذي 3747', grade: 'صحيح',
    tags: ['الصحابة']),
  Hadith(id: 'P19-H006', partNumber: 19, categoryId: 'cp_ahlulbayt',
    titleAr: 'الحسن والحسين', titleEn: 'Hasan & Husayn',
    narratorAr: 'البراء بن عازب رضي الله عنه', narratorEn: 'Al-Bara ibn Azib',
    textAr: 'الْحَسَنُ وَالْحُسَيْنُ سَيِّدَا شَبَابِ أَهْلِ الْجَنَّةِ.',
    textEn: 'Hasan and Husayn are the masters of the youth of Paradise.',
    source: 'جامع الترمذي 3768', grade: 'حسن صحيح',
    tags: ['الحسن', 'الحسين']),
  Hadith(id: 'P19-H007', partNumber: 19, categoryId: 'cp_sahaba',
    titleAr: 'عمار تقتله الفئة الباغية', titleEn: 'Ammar & the Transgressing Group',
    narratorAr: 'أبو سعيد الخدري رضي الله عنه', narratorEn: 'Abu Sa\'id al-Khudri',
    textAr: 'وَيْحَ عَمَّارٍ، تَقْتُلُهُ الْفِئَةُ الْبَاغِيَةُ، يَدْعُوهُمْ إِلَى الْجَنَّةِ وَيَدْعُونَهُ إِلَى النَّارِ.',
    textEn: 'Woe to Ammar — the transgressing group will kill him. He calls them to Paradise and they call him to the Fire.',
    source: 'صحيح البخاري 447', grade: 'صحيح',
    tags: ['عمار']),
  Hadith(id: 'P19-H008', partNumber: 19, categoryId: 'cp_sahaba',
    titleAr: 'أمانة أبي عبيدة', titleEn: 'Trust of Abu Ubaydah',
    narratorAr: 'حذيفة بن اليمان رضي الله عنه', narratorEn: 'Hudhayfah ibn al-Yaman',
    textAr: 'إِنَّ لِكُلِّ أُمَّةٍ أَمِينًا، وَإِنَّ أَمِينَنَا أَيَّتُهَا الْأُمَّةُ أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ.',
    textEn: 'Every nation has a trustee, and the trustee of this Ummah is Abu Ubaydah ibn al-Jarrah.',
    source: 'صحيح البخاري 3744 • صحيح مسلم 2419', grade: 'صحيح • متفق عليه',
    tags: ['أبو عبيدة', 'الأمانة']),
  Hadith(id: 'P19-H009', partNumber: 19, categoryId: 'cp_sahaba',
    titleAr: 'بيعة الرضوان', titleEn: 'Pledge of Ridwan',
    narratorAr: 'جابر بن عبد الله رضي الله عنهما', narratorEn: 'Jabir ibn Abdullah',
    textAr: 'لَا يَدْخُلُ النَّارَ أَحَدٌ مِمَّنْ بَايَعَ تَحْتَ الشَّجَرَةِ.',
    textEn: 'No one who pledged allegiance under the tree will enter the Fire.',
    source: 'صحيح مسلم 2496', grade: 'صحيح',
    tags: ['بيعة الرضوان']),
  Hadith(id: 'P19-H010', partNumber: 19, categoryId: 'cp_sahaba',
    titleAr: 'خير الناس قرني', titleEn: 'Best Generation',
    narratorAr: 'عبد الله بن مسعود رضي الله عنه', narratorEn: 'Abdullah ibn Masud',
    textAr: 'خَيْرُ النَّاسِ قَرْنِي، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْ.',
    textEn: 'The best of people are my generation, then those who follow them, then those who follow them.',
    source: 'صحيح البخاري 2652 • صحيح مسلم 2533', grade: 'صحيح • متفق عليه',
    tags: ['الصحابة', 'التابعون']),
];

