    textAr: 'جَاءَ رَجُلٌ إِلَى النَّبِيِّ ﷺ فَقَالَ: الرَّجُلُ يُقَاتِلُ لِلْمَغْنَمِ، وَالرَّجُلُ يُقَاتِلُ لِلذِّكْرِ، وَالرَّجُلُ يُقَاتِلُ لِيُرَى مَكَانُهُ، فَمَنْ فِي سَبِيلِ اللَّهِ؟ قَالَ: مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ الْعُلْيَا فَهُوَ فِي سَبِيلِ اللَّهِ.',
    textEn: 'A man came to the Prophet ﷺ and asked: A man fights for spoils, another fights for reputation, another fights to be seen — who is in the way of Allah? He said: "Whoever fights so that the Word of Allah is supreme, he is in the way of Allah."',
    source: 'صحيح البخاري 2810 • صحيح مسلم 1904', grade: 'صحيح • متفق عليه',
    tags: ['الجهاد', 'الإخلاص']),
