    textAr: 'سَأَلْتُ رَسُولَ اللَّهِ ﷺ أَيُّ الْعَمَلِ أَفْضَلُ؟ قَالَ: إِيمَانٌ بِاللَّهِ وَجِهَادٌ فِي سَبِيلِهِ.',
