    tags: ['الغدر']),
  Hadith(id: 'P20-H005', partNumber: 20, categoryId: 'j_rules',
    titleAr: 'قتل المعاهد', titleEn: 'Killing a Covenanted Person',
    narratorAr: 'عبد الله بن عمرو رضي الله عنهما', narratorEn: 'Abdullah ibn Amr',
