    textAr: 'وَاللَّهِ لَا يَغُلُّ أَحَدٌ مِنْكُمْ مِنِّي شَيْئًا إِلَّا جَاءَ بِهِ يَوْمَ الْقِيَامَةِ يَحْمِلُهُ.',
