    narratorAr: 'ابن عباس رضي الله عنهما', narratorEn: 'Ibn Abbas',
    textAr: 'عَيْنَانِ لَا تَمَسُّهُمَا النَّارُ: عَيْنٌ بَكَتْ مِنْ خَشْيَةِ اللَّهِ، وَعَيْنٌ بَاتَتْ تَحْرُسُ فِي سَبِيلِ اللَّهِ.',
    textEn: 'Two eyes will not be touched by the Fire: an eye that wept out of fear of Allah, and an eye that stayed awake guarding in the way of Allah.',
