    tags: ['الحراسة', 'خشية الله']),
  Hadith(id: 'P20-H010', partNumber: 20, categoryId: 'j_reward',
    titleAr: 'من جهز غازيًا', titleEn: 'Equipping a Warrior',
    narratorAr: 'زيد بن خالد الجهني رضي الله عنه', narratorEn: 'Zayd ibn Khalid al-Juhani',
    textAr: 'مَنْ جَهَّزَ غَازِيًا فِي سَبِيلِ اللَّهِ فَقَدْ غَزَا، وَمَنْ خَلَفَ غَازِيًا فِي أَهْلِهِ بِخَيْرٍ فَقَدْ غَزَا.',
