    textEn: 'Do you know who the bankrupt one is? ... The bankrupt of my Ummah is the one who comes on the Day of Judgment with prayer, fasting, and zakat, but he insulted this one, slandered that one, consumed the wealth of this one, shed the blood of that one, and struck this one.',
